namespace LucyDesktop {
 public class ReportSection {public string Title;public List<string> Paragraphs=new List<string>();public List<string[]> Rows=new List<string[]>();public string[] Headers;}
 public class CareReport {public string Title,Intro;public List<ReportSection> Sections=new List<ReportSection>();}
 public static class ProductKnowledge {
  public static readonly string[] Categories={"Nemlendirici","Güneş koruyucu","Retinoid veya retinol","C vitamini","Temizleyici","Diğer"};
  public static string Info(string category){switch(category){
   case "Nemlendirici":return "Nemlendiriciler cildin su tutmasına yardımcı olur. Kendi kuruluk ve gerginlik gözlemini izleyebilirsin; belirli sürede kişisel iyileşme garantisi çıkarılmaz. Kaynak: https://www.aad.org/public/everyday-care/skin-care-basics/dry/pick-moisturizer";
   case "Güneş koruyucu":return "Güneşten korunma, koyu leke bakımının temel parçalarındandır. Bu bir koruma adımıdır; bir haftalık kayıttan lekelerin ne kadar açılacağı hesaplanamaz. Kaynak: https://www.aad.org/public/everyday-care/skin-care-secrets/routine/fade-dark-spots";
   case "Retinoid veya retinol":return "Retinoidler hafif akne, ton eşitsizliği ve ince çizgiler için kullanılabilir; tahriş oluşturabilir. Retinoidler gebelikte kullanılmaz. Kişiye özel sonuç süresi ve tedavi değişikliği bu günlükten çıkarılmaz. Kaynak: https://www.aad.org/public/everyday-care/skin-care-secrets/anti-aging/retinoid-retinol/";
   case "C vitamini":return "C vitamini koyu leke görünümünü azaltmaya yardımcı olabilen içeriklerdendir. Formül ve cilt özellikleri sonucu değiştirir; ürün adından kişisel etki yüzdesi ya da kesin süre hesaplanmaz. Kaynak: https://www.aad.org/public/everyday-care/skin-care-secrets/routine/fade-dark-spots";
   case "Temizleyici":return "Bu ürün için temizleme alışkanlığı ve kendi rahatlık ya da gerginlik gözlemin kaydedilir. Temizleyici kullanımından leke veya kırışıklıkta iyileşme varsayılmaz.";
   default:return "Bu ürün için doğrulanmış bir içerik sınıfı seçilmediğinden beklenen cilt değişimi çıkarılmadı. Etiket bilgisini ve kendi gözlemini kaydedebilirsin.";
  }}
 }
 public static class Reports {
  static readonly CultureInfo Tr=CultureInfo.GetCultureInfo("tr-TR");
  public static DateTime WeekStart(DateTime date){return date.Date.AddDays(-(((int)date.DayOfWeek+6)%7));}
  public static CareReport Build(Preferences p,DateTime start,DateTime end,bool monthly){
   var result=new CareReport{Title=monthly?"Aylık kişisel bakım ilerleme raporu":"Haftalık kişisel bakım raporu"};string first=Tracking.Key(start),last=Tracking.Key(end);var plans=p.Plans.Where(x=>string.CompareOrdinal(x.Date,first)>=0&&string.CompareOrdinal(x.Date,last)<=0&&SectionNames.IsCare(p,x.Group)).ToList();var logs=p.TaskLogs.Where(x=>string.CompareOrdinal(x.Date,first)>=0&&string.CompareOrdinal(x.Date,last)<=0).ToList();var records=p.RoutineRecords.Where(x=>string.CompareOrdinal(x.Date,first)>=0&&string.CompareOrdinal(x.Date,last)<=0&&SectionNames.IsCare(p,x.Group)).OrderBy(x=>x.Date).ThenBy(x=>x.Group).ToList();
   int completed=plans.Count(i=>logs.LastOrDefault(l=>l.Date==i.Date&&l.TaskId==i.TaskId)!=null&&logs.Last(l=>l.Date==i.Date&&l.TaskId==i.TaskId).Done);bool open=DateTime.Now<=end.Date.AddDays(1).AddHours(12);
   result.Intro=start.ToString("d MMMM yyyy",Tr)+" ile "+end.ToString("d MMMM yyyy",Tr)+" arasında kayıtlı "+plans.Count+" bakım görevinin "+completed+" tanesi tamamlandı. "+(open?"Dönem veya geç kayıt penceresi henüz kapanmadı; bu bir ara rapordur.":"Dönemin kayıt penceresi kapandı.")+" Planı bulunmayan günler başarı oranına dahil edilmez.";
   var summary=new ReportSection{Title="Rutin özeti",Headers=new[]{"Rutin","Planlı görev","Tamamlanan","Kayıtlı gün"}};
   foreach(var group in new[]{"morning","evening"}.Concat(plans.Select(i=>i.Group)).Distinct()){var items=plans.Where(i=>i.Group==group).ToList();int done=items.Count(i=>logs.LastOrDefault(l=>l.Date==i.Date&&l.TaskId==i.TaskId)!=null&&logs.Last(l=>l.Date==i.Date&&l.TaskId==i.TaskId).Done);summary.Rows.Add(new[]{group=="morning"?"Sabah":group=="evening"?"Akşam":SectionNames.Title(p,group),items.Count.ToString(),done.ToString(),records.Count(r=>r.Group==group).ToString()});}result.Sections.Add(summary);
   var daily=new ReportSection{Title="Günlük kayıtlar",Headers=new[]{"Tarih","Sabah","Akşam","Su ml","Kafein mg"}};
   for(var date=start.Date;date<=end.Date;date=date.AddDays(1)){string key=Tracking.Key(date);Func<string,string> cell=group=>{var planned=plans.Where(i=>i.Date==key&&i.Group==group).ToList();var record=records.LastOrDefault(r=>r.Date==key&&r.Group==group);if(date>DateTime.Today)return "Henüz gelmedi";if(planned.Count==0)return record==null?"Plan kaydı yok":record.Status;int done=planned.Count(i=>logs.LastOrDefault(l=>l.Date==key&&l.TaskId==i.TaskId)!=null&&logs.Last(l=>l.Date==key&&l.TaskId==i.TaskId).Done);return done+"/"+planned.Count+(record!=null&&record.Status=="Bugün atladım"?" atlandı":"");};var drinks=p.Drinks.Where(d=>d.Date==key).ToList();daily.Rows.Add(new[]{date.ToString("dd.MM.yyyy"),cell("morning"),cell("evening"),drinks.Any(d=>d.Type=="water")?(drinks.Any(d=>d.Type=="water"&&d.Ml.HasValue)?Tracking.Water(p,date).ToString("0")+(drinks.Any(d=>d.Type=="water"&&!d.Ml.HasValue)?" + bilinmeyen":""):"Hacim bilinmiyor"):"Kayıt yok",drinks.Any(d=>d.Type!="water")?Tracking.Caffeine(p,date).ToString("0.#")+(Tracking.UnknownCaffeine(p,date)>0?" + bilinmeyen":""):"Kayıt yok"});}result.Sections.Add(daily); var steps=new ReportSection{Title="Tamamlanan bakım adımları",Headers=new[]{"Tarih","Rutin","Görev"}};foreach(var log in logs.Where(l=>l.Done&&SectionNames.IsCare(p,l.Group)).OrderBy(l=>l.Date).ThenBy(l=>l.Group))steps.Rows.Add(new[]{log.Date,log.Group=="morning"?"Sabah":log.Group=="evening"?"Akşam":SectionNames.Title(p,log.Group),log.Title});if(steps.Rows.Count==0)steps.Paragraphs.Add("Bu dönemde tamamlanan bakım adımı kaydedilmedi.");result.Sections.Add(steps);
   var diary=new ReportSection{Title="Bakım notları"};foreach(var record in records){var names=p.Products.Where(product=>record.ProductIds!=null&&record.ProductIds.Contains(product.Id)).Select(product=>product.Name);string text=record.Date+" "+(record.Group=="morning"?"sabah":record.Group=="evening"?"akşam":SectionNames.Title(p,record.Group))+" "+record.Status;if(!string.IsNullOrWhiteSpace(record.Note))text+=". "+record.Note;if(names.Any())text+=". Kullanılan ürünler: "+string.Join(", ",names)+".";diary.Paragraphs.Add(text);}if(diary.Paragraphs.Count==0)diary.Paragraphs.Add("Bu dönemde ayrıca kaydedilmiş bir bakım notu yok.");result.Sections.Add(diary);
   var observations=new ReportSection{Title="Kendi cilt gözlemlerin"};Action<string,Func<RoutineRecord,int?>> observation=(name,get)=>{var values=records.Where(r=>get(r).HasValue).ToList();if(values.Count>=2)observations.Paragraphs.Add(name+": ilk kayıt "+values.First().Date+" puan "+get(values.First())+", son kayıt "+values.Last().Date+" puan "+get(values.Last())+". Bunlar 0 ile 5 arasında kendi puanlamandır; ürünün etkisini veya tanı sonucunu göstermez.");else observations.Paragraphs.Add(name+": "+(values.Count==0?"henüz puan kaydı yok.":"tek puan kaydı var; değişim hesaplanmadı."));};observation("Kuruluk",r=>r.Dryness);observation("Kızarıklık",r=>r.Redness);observation("Sivilce görünümü",r=>r.Blemishes);result.Sections.Add(observations);
   var products=new ReportSection{Title="Ürünler ve genel bilgiler"};foreach(var product in p.Products.Where(product=>product.Active||records.Any(record=>record.ProductIds!=null&&record.ProductIds.Contains(product.Id)))){int uses=records.Count(record=>record.ProductIds!=null&&record.ProductIds.Contains(product.Id));products.Paragraphs.Add(product.Name+". Bu dönemde "+uses+" kullanım kaydı. "+(!string.IsNullOrWhiteSpace(product.Ingredients)?"Etiketten girdiğin içerikler: "+product.Ingredients+". ":"")+ProductKnowledge.Info(product.Category));}if(products.Paragraphs.Count==0)products.Paragraphs.Add("Güncel ürün kaydı eklenmedi. Ürünlere göre beklenen değişim çıkarılmadı. Ürünlerim sayfasından güncel ürünlerini ekleyebilirsin.");result.Sections.Add(products);
   var methods=new ReportSection{Title="Hesaplama ve kaynaklar"};methods.Paragraphs.Add("Rutin özeti günlük plan ve tarihli tik kayıtlarından hesaplanır. Geçmişte toplanmamış kayıtlar tahmin edilmez. Su toplamı yalnızca kaydedilen su miktarıdır; kahve su toplamına eklenmez. Kafein hesabı kaydedilmiş içeceklerin bilinen veya referansla tahmin edilen mg değerlerini toplar; belirtilmeyenler ayrıca gösterilir.");methods.Paragraphs.Add("Kafein referansı EFSA: filtre kahve 200 ml için yaklaşık 90 mg; espresso 60 ml için yaklaşık 80 mg; siyah çay 220 ml için yaklaşık 50 mg. Ürün ve hazırlama yöntemine göre değişir. https://www.efsa.europa.eu/en/topics/topic/caffeine");methods.Paragraphs.Add("Granül kahve tahmini, NESCAFÉ üretici örneğindeki 2 g için 50–90 mg aralığının orta değeri 70 mg üzerinden gramla ölçeklenir. Markaya göre değişir; kullanıcı mg girdiyse o değer kullanılır. Eklenen su kafeini artırmaz. https://www.nescafe.com/faq");methods.Paragraphs.Add("Türk kahvesi tahmininde 60 ml için 60 mg referansı kullanılır. Bu, ürünün ölçülmüş kafein değeri değildir; miktar ve adetle ölçeklenir.");result.Sections.Add(methods);return result;
  }
  static string X(string s){return SecurityElement.Escape(s??"");}
  public static string Export(Preferences p,DateTime start,DateTime end,bool monthly,string folder=null){
   var report=Build(p,start,end,monthly);folder=folder??System.IO.Path.Combine(Store.Root,"Raporlar");Directory.CreateDirectory(folder);string name=start.ToString("yyyy-MM-dd")+(monthly?"-aylik-rapor":"-haftalik-rapor");string path=System.IO.Path.Combine(folder,name+".docx");WriteDocx(report,path);File.WriteAllText(System.IO.Path.ChangeExtension(path,"html"),Html(report),Encoding.UTF8);return path;
  }
  public static void Open(string path){try{Process.Start(new ProcessStartInfo(path){UseShellExecute=true});}catch(Exception e){Store.Log(e);System.Windows.MessageBox.Show("Rapor kaydedildi: "+path,"Lucy");}}
  static string Html(CareReport report){var b=new StringBuilder("<!doctype html><html lang='tr'><meta charset='utf-8'><title>"+X(report.Title)+"</title><style>body{font:15px/1.6 Arial;color:#202020;max-width:900px;margin:40px auto;padding:20px}h1{font-size:28px}h2{font-size:20px;margin-top:28px}table{border-collapse:collapse;width:100%;margin:15px 0}td,th{border:1px solid #d9d9d9;padding:8px;text-align:left}th{background:#e8edf4}p{overflow-wrap:anywhere}@media print{body{margin:0;max-width:none}tr{break-inside:avoid}h2{break-after:avoid}thead{display:table-header-group}}</style><h1>"+X(report.Title)+"</h1><p>"+X(report.Intro)+"</p>");foreach(var section in report.Sections){b.Append("<h2>"+X(section.Title)+"</h2>");foreach(var text in section.Paragraphs)b.Append("<p>"+X(text)+"</p>");if(section.Rows.Count>0){b.Append("<table><thead><tr>");foreach(var header in section.Headers)b.Append("<th>"+X(header)+"</th>");b.Append("</tr></thead><tbody>");foreach(var row in section.Rows){b.Append("<tr>");foreach(var cell in row)b.Append("<td>"+X(cell)+"</td>");b.Append("</tr>");}b.Append("</tbody></table>");}}return b.Append("</html>").ToString();}
  static string Paragraph(string text,string style="Normal"){return "<w:p><w:pPr><w:pStyle w:val='"+style+"'/></w:pPr><w:r><w:t xml:space='preserve'>"+X(text)+"</w:t></w:r></w:p>";}
  static void Put(ZipArchive zip,string name,string text){var entry=zip.CreateEntry(name);using(var writer=new StreamWriter(entry.Open(),new UTF8Encoding(false)))writer.Write(text);}
  static void WriteDocx(CareReport report,string path){
   var b=new StringBuilder("<?xml version='1.0' encoding='UTF-8' standalone='yes'?><w:document xmlns:w='http://schemas.openxmlformats.org/wordprocessingml/2006/main'><w:body>");b.Append(Paragraph(report.Title,"Title")).Append(Paragraph(report.Intro));
   foreach(var section in report.Sections){b.Append(Paragraph(section.Title,"Heading1"));foreach(var text in section.Paragraphs)b.Append(Paragraph(text));if(section.Rows.Count>0){int count=section.Headers.Length;int total=9360;int first=count==5||count==3?1660:3000;int rest=(total-first)/(count-1);b.Append("<w:tbl><w:tblPr><w:tblW w:w='9360' w:type='dxa'/><w:tblLayout w:type='fixed'/><w:tblBorders>");foreach(var edge in new[]{"top","left","bottom","right","insideH","insideV"})b.Append("<w:"+edge+" w:val='single' w:sz='4' w:color='D9D9D9'/>");b.Append("</w:tblBorders><w:tblCellMar><w:top w:w='100' w:type='dxa'/><w:left w:w='110' w:type='dxa'/><w:bottom w:w='100' w:type='dxa'/><w:right w:w='110' w:type='dxa'/></w:tblCellMar></w:tblPr><w:tblGrid>");for(int i=0;i<count;i++)b.Append("<w:gridCol w:w='"+(i==0?first:rest)+"'/>");b.Append("</w:tblGrid>");var rows=new List<string[]>();rows.Add(section.Headers);rows.AddRange(section.Rows);for(int ri=0;ri<rows.Count;ri++){b.Append("<w:tr><w:trPr><w:cantSplit/>"+(ri==0?"<w:tblHeader/>":"")+"</w:trPr>");for(int ci=0;ci<count;ci++){b.Append("<w:tc><w:tcPr><w:tcW w:w='"+(ci==0?first:rest)+"' w:type='dxa'/><w:vAlign w:val='center'/>"+(ri==0?"<w:shd w:fill='E8EDF4'/>":"")+"</w:tcPr><w:p><w:pPr><w:spacing w:after='0'/></w:pPr><w:r><w:rPr>"+(ri==0?"<w:b/>":"")+"<w:sz w:val='20'/><w:color w:val='000000'/></w:rPr><w:t xml:space='preserve'>"+X(rows[ri][ci])+"</w:t></w:r></w:p></w:tc>");}b.Append("</w:tr>");}b.Append("</w:tbl>").Append(Paragraph(""));}}
   b.Append("<w:sectPr><w:pgSz w:w='12240' w:h='15840'/><w:pgMar w:top='1200' w:bottom='1200' w:left='1440' w:right='1440'/></w:sectPr></w:body></w:document>");
   using(var f=File.Create(path))using(var zip=new ZipArchive(f,ZipArchiveMode.Create)){
    Put(zip,"[Content_Types].xml","<?xml version='1.0'?><Types xmlns='http://schemas.openxmlformats.org/package/2006/content-types'><Default Extension='rels' ContentType='application/vnd.openxmlformats-package.relationships+xml'/><Default Extension='xml' ContentType='application/xml'/><Override PartName='/word/document.xml' ContentType='application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml'/><Override PartName='/word/styles.xml' ContentType='application/vnd.openxmlformats-officedocument.wordprocessingml.styles+xml'/></Types>");
    Put(zip,"_rels/.rels","<?xml version='1.0'?><Relationships xmlns='http://schemas.openxmlformats.org/package/2006/relationships'><Relationship Id='rId1' Type='http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument' Target='word/document.xml'/></Relationships>");
    Put(zip,"word/_rels/document.xml.rels","<?xml version='1.0'?><Relationships xmlns='http://schemas.openxmlformats.org/package/2006/relationships'><Relationship Id='rId1' Type='http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles' Target='styles.xml'/></Relationships>");
    Put(zip,"word/styles.xml","<?xml version='1.0'?><w:styles xmlns:w='http://schemas.openxmlformats.org/wordprocessingml/2006/main'><w:docDefaults><w:rPrDefault><w:rPr><w:rFonts w:ascii='Arial' w:hAnsi='Arial'/><w:sz w:val='22'/><w:color w:val='000000'/></w:rPr></w:rPrDefault><w:pPrDefault><w:pPr><w:spacing w:after='140' w:line='276' w:lineRule='auto'/></w:pPr></w:pPrDefault></w:docDefaults><w:style w:type='paragraph' w:default='1' w:styleId='Normal'><w:name w:val='Normal'/></w:style><w:style w:type='paragraph' w:styleId='Title'><w:name w:val='Title'/><w:basedOn w:val='Normal'/><w:pPr><w:keepNext/><w:spacing w:after='240'/></w:pPr><w:rPr><w:b/><w:sz w:val='44'/><w:color w:val='000000'/></w:rPr></w:style><w:style w:type='paragraph' w:styleId='Heading1'><w:name w:val='heading 1'/><w:basedOn w:val='Normal'/><w:pPr><w:keepNext/><w:spacing w:before='240' w:after='140'/><w:outlineLvl w:val='0'/></w:pPr><w:rPr><w:b/><w:sz w:val='28'/><w:color w:val='000000'/></w:rPr></w:style></w:styles>");Put(zip,"word/document.xml",b.ToString());
   }
  }
  public static TrackingPrompt FinalizeDue(Preferences p,DateTime now){if(Store.TestMode)return null;DateTime since;if(!DateTime.TryParse(p.TrackingSince,out since))return null;var closed=WeekStart(now);if(now<closed.AddHours(12))closed=closed.AddDays(-7);for(var week=WeekStart(since);week<closed;week=week.AddDays(7)){string key="weekly-report:"+Tracking.Key(week);if(p.PromptKeys.Contains(key))continue;try{Export(p,week,week.AddDays(6),false);p.PromptKeys.Add(key);return new TrackingPrompt{Title="Haftalık bakım raporun hazır",Text="Küçük adımlarını bir araya getirdim. Haftalık raporunu kişisel bakım menüsünden açabilirsin.",Page="weekly",Date=week};}catch(Exception e){Store.Log(e);return null;}}return null;}
 }
}
